$('.main-content').appendChild(sectorsPage);hydrateIcons(sectorsPage);attachChartInteractions($('#sector-page-candle'));
function boardChange(board){return board.change*boardRangeFactors[boardRange]+(boardRange==='今日'?0:((board.seed%3)-1)*.22)}
function boardSpark(board,change){const values=[];let value=30;for(let i=0;i<12;i++){value+=((i*board.seed)%5-2)*.65+(change>=0?.9:-.9);values.push(value.toFixed(1))}return values.join(',')}
function boardTypeMark(board){return board.type==='概念'?'概':board.type==='行业'?'行':'自'}
function renderBoardTable(){let boards=allBoards.filter(board=>(boardTypeFilter==='全部'||board.type===boardTypeFilter)&&(!boardQuery||`${board.name}${board.leader}`.toLowerCase().includes(boardQuery)));const tbody=$('.sectors-all-table tbody');tbody.innerHTML=boards.map(board=>{const change=boardChange(board);return`<tr data-board-name="${board.name}" class="${board.name===activeBoard?'selected':''}"><td><button class="favorite-sector${favoriteBoards.includes(board.name)?' active':''}" data-board-favorite="${board.name}"><i data-icon="star"></i></button><span class="board-type ${board.type==='行业'?'industry':'concept'}">${boardTypeMark(board)}</span><strong>${board.name}</strong></td><td class="num strong ${change>=0?'up':'down'}">${signed(change)}</td><td><div class="sparkline ${change>=0?'up-line':'down-line'}" data-spark="${boardSpark(board,change)}"></div></td><td class="num">${board.amount.toFixed(1)} 亿</td><td class="num ${board.delta>=0?'up':'down'}">${signed(board.delta)}</td><td class="num"><span class="up">${board.up}</span> / <span class="down">${board.down}</span></td><td>${board.leader} <span class="${board.leaderChange>=0?'up':'down'}">${signed(board.leaderChange)}</span></td><td class="num sector-flow ${board.flow===null?'muted-text':board.flow>=0?'up':'down'}">${board.flow===null?'—':signed(board.flow)}</td></tr>`}).join('')||'<tr><td colspan="8"><div class="group-empty">没有匹配的板块</div></td></tr>';hydrateIcons(tbody);$$('tr[data-board-name]',tbody).forEach(row=>row.addEventListener('click',()=>{activeBoard=row.dataset.boardName;renderBoardTable();renderBoardDetail()}));$$('[data-board-favorite]',tbody).forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();toggleBoardFavorite(btn.dataset.boardFavorite)}));$('#board-result-count').textContent=`${boards.length} 个板块 · 数据时间 10:32`;renderSparklines()}
function renderBoardDetail(){const board=allBoards.find(item=>item.name===activeBoard)||allBoards[0],change=boardChange(board);$('#sector-page-name').textContent=board.name;$('#sector-page-type').textContent=boardTypeMark(board);$('#sector-page-type').className=`board-type ${board.type==='行业'?'industry':'concept'}`;$('#sector-page-change').textContent=signed(change);$('#sector-page-change').className=change>=0?'up':'down';$('#sector-page-range').textContent=`${boardRange}表现 · ${board.type}`;$('#sector-page-amount').textContent=`${board.amount.toFixed(1)} 亿`;$('#sector-page-delta').textContent=signed(board.delta);$('#sector-page-delta').className=board.delta>=0?'up':'down';$('#sector-page-breadth').innerHTML=`<em class="up">${board.up}</em> / <em class="down">${board.down}</em>`;$('#sector-page-favorite').classList.toggle('active',favoriteBoards.includes(board.name));$('#sector-page-stocks').innerHTML=board.stocks.map((stock,i)=>`<tr><td><strong>${stock}</strong><small>${['300502','300308','300394'][i]||'300000'}</small></td><td class="num ${i===2&&board.change<0?'down':'up'}">${i===2&&board.change<0?'−0.82%':signed(board.leaderChange-i*.86)}</td><td class="num">${(board.amount/(i+2)/3).toFixed(1)} 亿</td></tr>`).join('');$('#sector-page-etf').innerHTML=`<button>${board.etf}<b class="up">${signed(board.change*.62)}</b></button><button>${board.type==='行业'?'主题 ETF':'行业 ETF'}<b class="up">${signed(board.change*.48)}</b></button>`;const chart=$('#sector-page-candle');chart._targetPrice=null;if(location.hash==='#sectors')requestAnimationFrame(()=>renderCandleChart(chart,board.seed,change>=0?'up':'down'))}
function toggleBoardFavorite(name){if(favoriteBoards.includes(name))favoriteBoards=favoriteBoards.filter(item=>item!==name);else favoriteBoards.push(name);renderBoardTable();renderBoardDetail();syncHomeBoardFavorites();toast(`${name}已${favoriteBoards.includes(name)?'加入':'移出'}自选板块`)}
function syncHomeBoardFavorites(){const tbody=$('.sector-table tbody');tbody.innerHTML=favoriteBoards.slice(0,6).map(name=>allBoards.find(board=>board.name===name)).filter(Boolean).map(board=>`<tr class="clickable" data-home-board="${board.name}"><td><span class="board-type ${board.type==='行业'?'industry':'concept'}">${boardTypeMark(board)}</span><strong>${board.name}</strong></td><td class="num ${board.change>=0?'up':'down'} strong">${signed(board.change)}</td><td class="num">${board.amount.toFixed(1)} 亿</td><td class="num ${board.delta>=0?'up':'down'}">${signed(board.delta)}</td><td class="num"><span class="up">${board.up}</span> / <span class="down">${board.down}</span></td><td>${board.leader} <span class="${board.leaderChange>=0?'up':'down'}">${signed(board.leaderChange)}</span></td><td><div class="sparkline ${board.change>=0?'up-line':'down-line'}" data-spark="${boardSpark(board,board.change)}"></div></td></tr>`).join('');$$('[data-home-board]',tbody).forEach(row=>row.addEventListener('click',()=>openBoardDrawer(allBoards.find(board=>board.name===row.dataset.homeBoard))));renderSparklines()}
function openBoardDrawer(board){activeBoard=board.name;$('#drawer-sector-name').textContent=board.name;$('.drawer-head .board-type').textContent=boardTypeMark(board);$('.drawer-head .soft-badge').textContent=board.type==='行业'?'申万二级行业':board.type==='概念'?'同花顺概念':'自定义板块';$('.drawer-section-head').hidden=false;$('.sector-detail-drawer>.data-table').hidden=false;$('.related-etf').hidden=false;const quote=$('.sector-quote');$('strong',quote).textContent=signed(board.change);$('strong',quote).className=board.change>=0?'up':'down';const spans=$$('span',quote);spans[0].innerHTML=`成交额 <b>${board.amount.toFixed(1)} 亿</b>`;spans[1].innerHTML=`较昨日 <b>${signed(board.delta)}</b>`;spans[2].innerHTML=`<b class="up">${board.up} 涨</b> / <b class="down">${board.down} 跌</b>`;$('.sector-detail-drawer>.data-table tbody').innerHTML=board.stocks.map((stock,i)=>`<tr><td><strong>${stock}</strong><small>30050${i}</small></td><td class="num">¥ ${(386.2-i*42.6).toFixed(2)}</td><td class="num up">${signed(board.leaderChange-i*.8)}</td><td class="num">${(board.amount/(i+2)/3).toFixed(1)} 亿</td><td><span class="research-state ${i===2?'todo':'done'}">${i===2?'待研究':'已完成'}</span></td></tr>`).join('');$('#sector-candle-chart')._targetPrice=null;$('#sector-drawer').hidden=false;requestAnimationFrame(()=>renderCandleChart($('#sector-candle-chart'),board.seed,board.change>=0?'up':'down'))}
function openSectorsPage(){switchPage('sectors');renderBoardTable();renderBoardDetail()}
