$$('[data-board-sort]').forEach(th=>{th.classList.add('sortable');th.addEventListener('click',()=>{const key=th.dataset.boardSort,asc=!th.classList.contains('sort-asc');$$('[data-board-sort]').forEach(el=>el.classList.remove('sort-asc','sort-desc'));th.classList.add(asc?'sort-asc':'sort-desc');const rows=$$('.sectors-all-table tbody tr[data-board-name]');rows.sort((a,b)=>{const av=key==='change'?boardChange(allBoards.find(board=>board.name===a.dataset.boardName)):allBoards.find(board=>board.name===a.dataset.boardName)[key],bv=key==='change'?boardChange(allBoards.find(board=>board.name===b.dataset.boardName)):allBoards.find(board=>board.name===b.dataset.boardName)[key];return asc?av-bv:bv-av});const tbody=$('.sectors-all-table tbody');rows.forEach(row=>tbody.appendChild(row))})});
$('#sector-page-favorite').addEventListener('click',()=>toggleBoardFavorite(activeBoard));
$$('#sector-page-periods button').forEach(btn=>btn.addEventListener('click',()=>{$$('#sector-page-periods button').forEach(el=>el.classList.remove('active'));btn.classList.add('active');const board=allBoards.find(item=>item.name===activeBoard);renderCandleChart($('#sector-page-candle'),board.seed+btn.textContent.length,board.change>=0?'up':'down')}));
$('#sector-open-drawer').addEventListener('click',()=>openBoardDrawer(allBoards.find(board=>board.name===activeBoard)));
$('#sector-filter-stocks').addEventListener('click',()=>{$('#drawer-sector-name').textContent=activeBoard;$('.drawer-section-head .button').click()});
$('#sector-view-constituents').addEventListener('click',()=>openBoardDrawer(allBoards.find(board=>board.name===activeBoard)));
$('#manage-boards-button').addEventListener('click',()=>{const modal=enhancedDialog('board-manager-dialog','管理自选板块','<p class="dialog-subtitle">首页按以下顺序显示前 6 个板块。可调整顺序或移除；在板块列表中点击星标可继续添加。</p><div id="board-manager-list"></div>',{actions:'<button class="button primary" id="save-board-manager">完成</button>'});function renderManager(){const list=$('#board-manager-list',modal);list.innerHTML=favoriteBoards.map((name,i)=>`<div class="sector-manager-row"><span>${String(i+1).padStart(2,'0')}</span><strong>${name}</strong><span>${i<6?'首页显示':'备选'}</span><button data-move-up="${i}" title="上移">↑</button><button data-move-down="${i}" title="下移">↓</button><button data-remove-board="${name}" title="移除">×</button></div>`).join('')||'<div class="group-empty">暂无自选板块</div>';$$('[data-move-up]',list).forEach(btn=>btn.addEventListener('click',()=>{const i=Number(btn.dataset.moveUp);if(i>0)[favoriteBoards[i-1],favoriteBoards[i]]=[favoriteBoards[i],favoriteBoards[i-1]];renderManager()}));$$('[data-move-down]',list).forEach(btn=>btn.addEventListener('click',()=>{const i=Number(btn.dataset.moveDown);if(i<favoriteBoards.length-1)[favoriteBoards[i+1],favoriteBoards[i]]=[favoriteBoards[i],favoriteBoards[i+1]];renderManager()}));$$('[data-remove-board]',list).forEach(btn=>btn.addEventListener('click',()=>{favoriteBoards=favoriteBoards.filter(name=>name!==btn.dataset.removeBoard);renderManager()}))}renderManager();$('#save-board-manager',modal).addEventListener('click',()=>{syncHomeBoardFavorites();renderBoardTable();renderBoardDetail();closeEnhancedDialog('board-manager-dialog');toast('自选板块顺序已同步到首页')})});
$('#custom-board-button').addEventListener('click',()=>{const modal=enhancedDialog('custom-board-dialog','新建自定义板块','<div class="custom-board-form"><label>板块名称<input id="custom-board-name" value="我的算力链"/></label><div><span style="display:block;font-size:10px;color:var(--muted);margin-bottom:7px">选择成分股</span><div class="custom-board-stocks"><label><input type="checkbox" checked value="新易盛"/>新易盛</label><label><input type="checkbox" checked value="中际旭创"/>中际旭创</label><label><input type="checkbox" checked value="天孚通信"/>天孚通信</label><label><input type="checkbox" value="寒武纪"/>寒武纪</label><label><input type="checkbox" value="浪潮信息"/>浪潮信息</label><label><input type="checkbox" value="中科曙光"/>中科曙光</label></div></div><p class="modal-note">软件会按成分股合成一条板块走势，并与官方行业、概念放在一起比较。</p></div>',{actions:'<button class="button primary" id="save-custom-board">创建板块</button>'});$('#save-custom-board',modal).addEventListener('click',()=>{const name=$('#custom-board-name',modal).value.trim(),stocks=$$('.custom-board-stocks input:checked',modal).map(input=>input.value);if(!name||!stocks.length){toast('请填写名称并至少选择一只股票');return}allBoards.push({name,type:'自定义',change:2.68,amount:196.8,delta:18.6,up:stocks.length,down:0,leader:stocks[0],leaderChange:6.18,flow:null,etf:'通信 ETF',seed:76,stocks});favoriteBoards.push(name);activeBoard=name;boardTypeFilter='自定义';$$('[data-board-type]').forEach(el=>el.classList.toggle('active',el.dataset.boardType==='自定义'));renderBoardTable();renderBoardDetail();syncHomeBoardFavorites();closeEnhancedDialog('custom-board-dialog');toast(`已创建自定义板块“${name}”`)})});
document.addEventListener('keydown',e=>{if(e.key==='6'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!e.metaKey&&!e.ctrlKey)openSectorsPage()});
renderBoardTable();renderBoardDetail();if(location.hash==='#sectors')openSectorsPage();
